import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Main {
    static final int MOD = 1_000_000_007;

    static int add(int a, int b) {
        a += b;
        if (a >= MOD) a -= MOD;
        return a;
    }

    static int mul(int a, int b) {
        return (int) ((long) a * b % MOD);
    }

    static class Mat {
        final int n;
        final int[][] a;

        Mat(int n) {
            this.n = n;
            a = new int[n][n];
        }

        Mat(Mat other) {
            n = other.n;
            a = new int[n][n];
            for (int i = 0; i < n; i++) {
                System.arraycopy(other.a[i], 0, a[i], 0, n);
            }
        }

        static Mat identity(int n) {
            Mat res = new Mat(n);
            for (int i = 0; i < n; i++) res.a[i][i] = 1;
            return res;
        }

        Mat multiply(Mat other) {
            Mat res = new Mat(n);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    int sum = 0;
                    for (int t = 0; t < n; t++) {
                        sum = add(sum, mul(a[i][t], other.a[t][j]));
                    }
                    res.a[i][j] = sum;
                }
            }
            return res;
        }

        Mat clone() {
            return new Mat(this);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split(" ");
            if (parts.length < 2) continue;
            long n = Long.parseLong(parts[0]);
            int k = Integer.parseInt(parts[1]);
            solve(n, k);
        }
    }

    static void solve(long n, int k) {
        // Build digits in base k (least significant first)
        List<Integer> num = new ArrayList<>();
        while (n > 0) {
            num.add((int) (n % k));
            n /= k;
        }

        if (num.isEmpty()) {
            System.out.println(1);
            return;
        }

        int sz = k + 1; // matrix size
        int d = num.size(); // number of digits

        // amat[r][shift] where r = digit index, shift = 0..k-1
        Mat[][] amat = new Mat[d][k];

        // Initialize for r = 0
        for (int shift = 0; shift < k; shift++) {
            Mat m = Mat.identity(sz);
            for (int i = 0; i < sz; i++) {
                m.a[i][shift] = 1; // set column 'shift' to 1
            }
            amat[0][shift] = m;
        }

        // Precompute for higher r
        for (int r = 1; r < d; r++) {
            // Prefix products: pr[0] = I, pr[i+1] = pr[i] * amat[r-1][i]
            List<Mat> pr = new ArrayList<>();
            pr.add(Mat.identity(sz));
            for (int i = 0; i < k; i++) {
                pr.add(pr.get(pr.size() - 1).multiply(amat[r - 1][i]));
            }

            for (int sh = 0; sh < k; sh++) {
                Mat cur = pr.get(0).clone(); // start with identity
                // Multiply by amat[r-1][sh], amat[r-1][sh+1], ..., up to k-1
                for (int i = 0; i < k - sh; i++) {
                    cur = cur.multiply(amat[r - 1][(i + sh) % k]);
                }
                // Multiply by prefix product of first sh matrices
                cur = cur.multiply(pr.get(sh));
                amat[r][sh] = cur;
            }
        }

        // dp is a row vector stored as a matrix (only first row matters)
        Mat dp = new Mat(sz);
        dp.a[0][k] = 1; // note: index k is valid because size = k+1

        int rem = 0;
        for (int i = d - 1; i >= 0; i--) {
            int cnt = num.get(i);
            while (cnt > 0) {
                dp = dp.multiply(amat[i][rem]);
                rem = (rem + 1) % k;
                cnt--;
            }
        }

        int ans = 0;
        for (int i = 0; i < sz; i++) {
            ans = add(ans, dp.a[0][i]);
        }
        System.out.println(ans);
    }
